    returns: () => card('', table(['Date', 'No.', 'Type', 'Reason', { t: 'Amount', c: 'n' }, { t: 'Refund', c: 'n' }], r.returns.filter(x => x.kind !== 'adv_refund').map(x => `<tr class="${x.voided == 1 ? 'void' : ''}"><td>${D(x.date)}</td><td>${esc(x.return_no)}${x.bill_no ? '<br><span class="xs muted">bill ' + esc(x.bill_no) + '</span>' : ''}</td><td>${{ return: 'Goods return', credit_note: 'Credit note', charge: 'Extra charge' }[x.kind] || esc(x.kind)}</td><td>${esc(x.reason)}</td><td class="n">${R(x.total, true)}</td><td class="n">${x.refund ? R(x.refund, true) : '—'}</td></tr>`), { none: 'No returns or notes' })
      + (cn.adjust ? `<div class="bd row"><button class="btn" data-a="sup-note" data-id="${s.id}" data-k="credit_note">＋ Credit note (reduces due)</button><button class="btn" data-a="sup-note" data-id="${s.id}" data-k="charge">＋ Extra charge (increases due)</button><button class="btn" data-a="sup-refund" data-id="${s.id}">＋ Refund received</button></div>` : '')),
