F.forms.supsave = async (f, d, _e, extra = {}) => { if (!moneyCheck(f, ['credit_limit'])) return; const photo = await fileToUpload(f.photo); const body = { ...d, id: d.id ? Number(d.id) : undefined, photo: photo || undefined, ...extra }; if (!d.pan) delete body.pan; if (!d.bank_account) delete body.bank_account; if (d.opening === undefined) delete body.opening;
  let r; try { r = await api('supplier-save', {}, body); } catch (e) { if (e.status === 409 && e.data?.needs === 'confirm_phone') { if (await ask('Same mobile number', esc(e.message), { ok: 'Save anyway' })) return F.forms.supsave(f, d, _e, { confirm_phone: 1 }); return; }
    if (e.status === 409 && e.data?.existing_id) { if (await ask('Already exists', esc(e.message), { ok: 'Use existing' })) { f.closest('.modal')._close(); if (f.dataset.forbill) { const g = await api('supplier', { id: e.data.existing_id }); F.A['pb-sup-pick']({ dataset: { id: g.supplier.id, name: g.supplier.name, phone: g.supplier.phone || '', gst: g.supplier.gstin || '', cd: g.supplier.credit_days } }); } else go('#/supplier/' + e.data.existing_id); } return; } throw e; }
  f.closest('.modal')._close(); toast('Supplier saved.');
  if (f.dataset.forbill) { const s = r.supplier; F.A['pb-sup-pick']({ dataset: { id: s.id, name: s.name, phone: s.phone || '', gst: s.gstin || '', cd: s.credit_days } }); } else if (!d.id) go('#/supplier/' + r.id); else render(); };

