F.forms.pay = async (f, d, _e, extra = {}) => { if (!moneyCheck(f, ['amount'])) return; const file = await fileToUpload(f.file);
  const allocations = d.allocate === 'manual' ? Object.entries(d).filter(([k, v]) => k.startsWith('b_') && v).map(([k, v]) => ({ bill_id: Number(k.slice(2)), amount: v })) : undefined;
  if (allocations) { const s = allocations.reduce((a, x) => a + (toPaise(x.amount) || 0), 0); if (s > toPaise(d.amount)) { toast('Bill amounts are more than the payment.', true); return; } }
  const body = { supplier_id: Number(f.dataset.sup), amount: d.amount, date: d.date, mode: d.mode, reference: d.reference, note: d.note, allocate: d.allocate, allocations, file: file || undefined, client_key: f.dataset.key ||= ikey(), ...extra };
  try { const r = await api('supplier-pay', {}, body); f.closest('.modal')._close(); toast(`Payment ${r.pay_no} saved${r.advance ? ' · ' + R(r.advance) + ' kept as advance' : ''}.`); render(); }
  catch (e) { if (e.status === 409 && e.data?.needs === 'ref_ok') { if (await ask('Reference used before', esc(e.message), { ok: 'Save anyway' })) { f.dataset.key = ikey(); return F.forms.pay(f, d, _e, { ref_ok: 1 }); } return; } throw e; } };
